import java.util.scanner;

public class predatorpreysimulation {

    private static double preypopulation;
    private static double predatorpopulation;
    private static double preybirthrate;
    private static double preydeathrate;
    private static double predatorbirthrate;
    private static double predatordeathrate;
    private static double timestep;

    private static final double min_population_size = 1;
    private static final double max_population_size = 1000;
    private static final double min_birth_rate = 0.001;
    private static final double max_birth_rate = 0.5;
    private static final double min_death_rate = 0.001;
    private static final double max_death_rate = 0.5;
    private static final double min_time_step = 0.01;
    private static final double max_time_step = 0.5;
    private static final double simulation_time = 50;

    public static void main(string[] args) {

        readuserinput();

        // running the simulation for specified time steps (50 days)
        for (double t = 0.0; t <= simulation_time; t += timestep) {

            double predatorchange = predatorbirthrate * preypopulation * predatorpopulation
                    - predatordeathrate * predatorpopulation;
            double preychange = preybirthrate * preypopulation - preydeathrate * predatorpopulation * preypopulation;

            predatorpopulation += predatorchange * timestep;
            preypopulation += preychange * timestep;

            // check for extinction
            if (preypopulation <= 0) {
                system.out.println("prey population exhausted at time: " + t);
                break;
            }
            if (predatorpopulation <= 0) {
                system.out.println("predator population exhausted at time: " + t);
                break;
            }
        }

        system.out.printf("final population - prey: %.2f, predator: %.2f%n", preypopulation, predatorpopulation);

    }

    /**
     * reads user input and verifies that it is within the specified range.
     * prompting user to input again if it falls outside the valid range.
     */
    private static void readuserinput() {
        scanner scanner = new scanner(system.in);

        system.out.print("enter initial prey population: ");
        preypopulation = verifyinput(scanner.nextdouble(), min_population_size, max_population_size);

        system.out.print("enter initial predator population: ");
        predatorpopulation = verifyinput(scanner.nextdouble(), min_population_size, max_population_size);

        system.out.print("enter prey birth rate: ");
        preybirthrate = verifyinput(scanner.nextdouble(), min_birth_rate, max_birth_rate);

        system.out.print("enter prey death rate: ");
        preydeathrate = verifyinput(scanner.nextdouble(), min_death_rate, max_death_rate);

        system.out.print("enter predator birth rate: ");
        predatorbirthrate = verifyinput(scanner.nextdouble(), min_birth_rate, max_birth_rate);

        system.out.print("enter predator death rate: ");
        predatordeathrate = verifyinput(scanner.nextdouble(), min_death_rate, max_death_rate);

        system.out.print("enter time step: ");
        timestep = verifyinput(scanner.nextdouble(), min_time_step, max_time_step);

        scanner.close();
    }

    /**
     * verifies user input is within the specified range
     * @param num input value
     * @param minvalue minimum acceptable value
     * @param maxvalue maximum acceptable value
     * @return input value
     */
    private static double verifyinput(double num, double minvalue, double maxvalue) {
        if (num < minvalue || num > maxvalue) {
            system.out.println("invalid value entered. Enter value again: ");
            scanner scanner = new scanner(system.in);
            num = verifyinput(scanner.nextdouble(), minvalue, maxvalue);
            scanner.close();
        }
        return num;
    }
}
